import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from './AuthContext';

function Auth() {
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [tenant, setTenant] = useState('default');
  const [message, setMessage] = useState('');
  const [profile, setProfile] = useState(null);
  const { token, setToken } = useAuth();

  useEffect(() => {
    if (token) {
      fetchProfile();
    } else {
      setProfile(null);
    }
  }, [token]);

  const fetchProfile = async () => {
    try {
      const res = await axios.get('/api/auth/me');
      setProfile(res.data);
    } catch (err) {
      setMessage(err.response?.data?.error || 'Failed to fetch profile.');
    }
  };

  const register = async () => {
    setMessage('');
    try {
      const res = await axios.post('/api/auth/register', {
        username,
        password,
        tenant_id: tenant,
      });
      setMessage(res.data.message);
    } catch (err) {
      setMessage(err.response?.data?.error || 'Registration failed.');
    }
  };

  const login = async () => {
    setMessage('');
    try {
      const res = await axios.post('/api/auth/login', {
        username,
        password,
        tenant_id: tenant,
      });
      setToken(res.data.token);
      setMessage('Login successful. Redirecting...');
      setTimeout(() => navigate('/malware'), 700);
    } catch (err) {
      setMessage(err.response?.data?.error || 'Login failed.');
    }
  };

  const logout = () => {
    setToken(null);
    setProfile(null);
    setMessage('Logged out.');
  };

  return (
    <div className="page-shell">
      <section className="hero-panel">
        <div>
          <span className="eyebrow">Identity</span>
          <h1>Secure App Access</h1>
          <p>Create an account, sign in, and unlock tenant-scoped malware and vulnerability workflows.</p>
        </div>
      </section>

      <section className="content-grid">
        <div className="glass-card">
          <h5 className="card-title">Authentication</h5>
          <div className="mb-2">
            <label className="form-label">Username</label>
            <input className="form-control" value={username} onChange={(e) => setUsername(e.target.value)} placeholder="username" />
          </div>
          <div className="mb-2">
            <label className="form-label">Tenant ID</label>
            <input className="form-control" value={tenant} onChange={(e) => setTenant(e.target.value)} placeholder="tenant id (e.g. default)" />
            <small className="form-text">Used to group users and scan history.</small>
          </div>
          <div className="mb-3">
            <label className="form-label">Password</label>
            <input
              type="password"
              className="form-control"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="password"
            />
          </div>
          <div className="d-flex flex-wrap gap-2">
            <button className="btn btn-outline-secondary" onClick={register}>
              Register
            </button>
            <button className="btn btn-primary" onClick={login}>
              Login
            </button>
            <button className="btn btn-outline-light" onClick={logout}>
              Logout
            </button>
          </div>
          {message && <div className="alert alert-info mt-3">{message}</div>}
        </div>

        <div className="glass-card">
          <h5 className="card-title">Profile</h5>
          {profile ? (
            <div className="stack-list">
              <div className="stack-item">
                <strong>Username</strong>
                <p>{profile.username}</p>
              </div>
              <div className="stack-item">
                <strong>Role</strong>
                <p>{profile.role}</p>
              </div>
              <div className="stack-item">
                <strong>Tenant</strong>
                <p>{profile.tenant_id}</p>
              </div>
            </div>
          ) : (
            <p className="text-muted">Login to view your profile.</p>
          )}
        </div>
      </section>
    </div>
  );
}

export default Auth;
